Use `line.trim().parse::<i64>()` and match both `Ok` and `Err`. This version uses only the standard library:

```rust
use std::{env, fs, process};

fn main() {
    let Some(path) = env::args().nth(1) else {
        eprintln!("usage: parse-integers <file>");
        process::exit(2);
    };

    let contents = match fs::read_to_string(&path) {
        Ok(contents) => contents,
        Err(error) => {
            eprintln!("could not read {path}: {error}");
            process::exit(2);
        }
    };

    let mut invalid_count = 0;
    for (index, line) in contents.lines().enumerate() {
        match line.trim().parse::<i64>() {
            Ok(number) => println!("line {}: {number}", index + 1),
            Err(_) => {
                invalid_count += 1;
                eprintln!("line {}: invalid integer: {line}", index + 1);
            }
        }
    }

    if invalid_count > 0 {
        process::exit(1);
    }
}
```

Run `rustc parse_integers.rs -o parse-integers`, then `./parse-integers numbers.txt`. Exit 0 means all lines parsed; exit 1 means at least one line was invalid; exit 2 means the path was missing or unreadable.

`enumerate()` pairs each item with a zero-based index. Add one when displaying a human-readable line number:

```rust
for (index, line) in contents.lines().enumerate() {
    println!("line {}: {line}", index + 1);
}
```

Rust string lines split on newline characters; an empty file yields no lines.
